import { effectiveOptions, numberRule, usage, valueLabel, type ArgDef, type CommandNode } from "./commandTree.js";
import { parse } from "./parse.js";

// The command reference page, rendered from the command tree — the same
// source `--help` and the palette read. Pure and deterministic: the same tree
// gives the same text (top-level commands sorted by name; children, options
// and examples in declared order). scripts/gen-command-reference.ts feeds it
// the registered tree and writes docs/reference/commands.md.

const HEADER = [
  "<!-- Generated by `npm run docs:reference` from the command tree (src/modules/**, src/core/builtins.ts).",
  "     Do not edit by hand: change the node's summary, description, arguments or examples in its module. -->",
  "",
  "# Command reference",
  "",
  "Every command of cmdAbl, generated from the declarations the platform itself parses, resolves and",
  "shows as help. Type a command in the palette; `<command> --help` prints the same information.",
].join("\n");

/** Prose for markdown: `&` and `<` escaped outside backtick spans (a bare `<id>` would be read as an HTML tag). */
function prose(text: string): string {
  return text
    .split(/(`[^`]*`)/)
    .map((part, i) => (i % 2 === 1 ? part : part.replace(/&/g, "&amp;").replace(/</g, "&lt;")))
    .join("");
}

const cell = (text: string): string => prose(text).replace(/\|/g, "\\|").replace(/\n/g, " ");

function argKind(arg: ArgDef): string {
  if (arg.kind === "enum" && arg.choices?.length) return `one of ${arg.choices.map((c) => `\`${c}\``).join(", ")}`;
  if (arg.kind === "path") {
    const kinds = arg.kinds?.length ? arg.kinds.join(" / ") : "any object";
    return `path (${kinds}${arg.multiple === "all" ? ", every match" : ""})`;
  }
  return arg.kind;
}

function argTable(args: ArgDef[]): string[] {
  const lines = ["| Argument | Kind | Required | Description |", "| --- | --- | --- | --- |"];
  for (const arg of args) {
    const name = `\`<${arg.name}>${arg.variadic ? "…" : ""}\``;
    const required = arg.required === false ? "no" : "yes";
    const description = [arg.summary ?? "", arg.rest ? "(takes the rest of the line)" : ""].filter(Boolean).join(" ");
    lines.push(`| ${name} | ${cell(argKind(arg))} | ${required} | ${cell(description)} |`);
  }
  return lines;
}

function renderNode(node: CommandNode<any, any>, path: string[], depth: number): string[] {
  const out: string[] = [];
  const heading = "#".repeat(Math.min(depth, 4));
  out.push("", `${heading} \`${path.join(" ")}\``, "", prose(node.summary));
  if (node.description) out.push("", prose(node.description));
  if (node.aliases?.length) out.push("", `Aliases: ${node.aliases.map((a) => `\`${a}\``).join(", ")}`);
  out.push("", `**Usage:** \`${usage(node, path)}\``);

  if (node.children?.length) {
    out.push("", "**Subcommands:** " + node.children.map((c) => `\`${c.name}\``).join(", "));
  }
  if (node.args?.length) out.push("", ...argTable(node.args));
  if (effectiveOptions(node).length) {
    out.push("", "| Option | Description |", "| --- | --- |");
    for (const opt of effectiveOptions(node)) {
      const flag = `${opt.short ? `-${opt.short}, ` : ""}--${opt.name}${opt.takesValue ? ` <${valueLabel(opt)}>` : ""}`;
      out.push(`| \`${flag}\` | ${cell(opt.summary + (opt.number ? ` (${numberRule(opt.number)})` : ""))} |`);
    }
  }
  const facts: string[] = [];
  if (node.requires?.includes("bridge")) facts.push("- Needs the Remote Script (reports \"not running\" / \"outdated\" otherwise).");
  if (node.destructive) facts.push("- Removes or irreversibly changes something; takes one target per address, never every match.");
  if (facts.length) out.push("", ...facts);
  if (node.examples?.length) {
    out.push("", "**Examples**", "");
    for (const example of node.examples) {
      out.push("```", example.line, "```");
      if (example.note) out.push("", prose(example.note), "");
    }
    if (out[out.length - 1] === "") out.pop();
    
  }
  for (const child of node.children ?? []) out.push(...renderNode(child, [...path, child.name], depth + 1));
  return out;
}

export function renderCommandReference(roots: CommandNode<any, any>[]): string {
  const sorted = [...roots].sort((a, b) => a.name.localeCompare(b.name, "en"));
  const body = sorted.flatMap((node) => renderNode(node, [node.name], 2));
  return [HEADER, ...body, ""].join("\n");
}

/**
 * Problems with the documentation of a tree (empty = fine): every runnable
 * command has an example, and every example parses against the tree (a
 * `--help` example may show another command's help; a run must be this
 * command) — so examples cannot rot. Resolution against a Live Set is not
 * attempted: an example only has to be valid syntax for its command.
 */
export function checkExamples(roots: CommandNode<any, any>[]): string[] {
  const problems: string[] = [];
  const walk = (node: CommandNode<any, any>, path: string[]): void => {
    const at = path.join(" ");
    if (node.children?.length) {
      for (const child of node.children) walk(child, [...path, child.name]);
      return;
    }
    if (!node.examples?.length) {
      problems.push(`${at}: no example`);
      return;
    }
    for (const example of node.examples) {
      const parsed = parse(example.line, roots);
      if (parsed.kind === "error") {
        problems.push(`${at}: example "${example.line}" does not parse: ${parsed.result.message ?? "error"}`);
      } else if (parsed.kind === "run" && parsed.node !== node) {
        problems.push(`${at}: example "${example.line}" runs "${parsed.invocation.path.join(" ")}", not this command`);
      }
    }
  };
  for (const root of roots) walk(root, [root.name]);
  return problems;
}

/** The Remote Script's operations, rendered for docs/reference/remote-script.md. */
export function renderRemoteScriptReference(
  ops: ReadonlyArray<{ name: string; summary: string; params?: string; changesLive: boolean }>,
  versions: { script: string; protocol: number },
): string {
  const lines = [
    "<!-- Generated by `npm run docs:reference` from src/ableton/remoteScriptOps.ts.",
    "     Do not edit by hand: change the operation's entry there. -->",
    "",
    "# Remote Script reference",
    "",
    "The companion Remote Script (Python, runs inside Live) does what the Extensions SDK cannot: it changes the",
    "selection, reads facts only the Live Object Model knows and mutes or solos rack chains. cmdAbl talks to it over a local socket with",
    "request/reply messages. `cmdabl setup` installs it, `cmdabl bridge` shows its status.",
    "",
    `Script version **${versions.script}**, protocol **v${versions.protocol}**.`,
    "",
    "| Operation | What it does | Parameters | Changes the Live Set |",
    "| --- | --- | --- | --- |",
  ];
  for (const op of ops) {
    const params = op.params ? `\`${op.params.replace(/\|/g, "\\|")}\`` : "–";
    lines.push(`| \`${op.name}\` | ${cell(op.summary)} | ${params} | ${op.changesLive ? "yes (needs the access token)" : "no"} |`);
  }
  lines.push("");
  return lines.join("\n");
}

// ── Live API mapping ────────────────────────────────────────────────────────

export interface LiveApiPort {
  port: string;
  via: "sdk" | "script" | "platform";
  call: string;
  lom: string[];
  note?: string;
}

/** One LOM member a script operation touches (the shape of ableton/remoteScriptOps.ts `LomUse`). */
export interface LiveApiLomUse {
  object: string;
  property: string;
  access: "get" | "set" | "call";
  page: string;
  type: string;
  documented: boolean;
  note?: string;
}

export interface LiveApiOp {
  name: string;
  summary: string;
  changesLive: boolean;
  lom: readonly LiveApiLomUse[];
  usesRoute: boolean;
  sdkAlternative: string;
}

export interface LiveApiInput {
  ports: readonly LiveApiPort[];
  ops: readonly LiveApiOp[];
  /** cmdAbl path ↔ LOM path: one example per kind (computed by the caller with `lomPath`). */
  pathExamples: ReadonlyArray<{ kind: string; scope: string; cmdablPath: string; lomPath: string }>;
  /** The LOM members used to walk `{scope, route}` (every operation with `usesRoute`). */
  routeLom: readonly LiveApiLomUse[];
  /** `Class.member` → documentation URL (ports table). */
  lomUrl: (name: string) => string;
  /** LOM class page slug → URL (script table). */
  pageUrl: (page: string) => string;
}

const SCOPE_LIST: ReadonlyArray<[string, string]> = [
  ["regular", "tracks"],
  ["return", "return_tracks"],
  ["master", "master_track"],
];

export function renderLiveApiReference(input: LiveApiInput): string {
  const link = (name: string) => `[\`${name}\`](${input.lomUrl(name)})`;
  const lomCell = (names: readonly string[]) => (names.length ? names.map(link).join(", ") : "–");
  const use = (u: LiveApiLomUse): string => {
    const name = `[\`${u.object}.${u.property}\`](${input.pageUrl(u.page)})`;
    const detail = [u.access, u.type, u.documented ? "" : "not in the LOM reference", u.note ?? ""].filter(Boolean).join("; ");
    return `${name} (${cell(detail)})`;
  };
  const lines = [
    "<!-- Generated by `npm run docs:reference` from src/modules/portMapping.ts, src/ableton/remoteScriptOps.ts and src/ableton/lomPath.ts.",
    "     Do not edit by hand: change the entry in its source. -->",
    "",
    "# Live API mapping",
    "",
    "Every path from a cmdAbl command to Live, oriented on the",
    "[Live Object Model](https://docs.cycling74.com/apiref/lom/). cmdAbl names things as the LOM does, so that a",
    "later switch from the Remote Script to an SDK call touches an adapter (`src/extension.ts`) and the entry in",
    "the tables below, not the modules.",
    "",
    "## cmdAbl path ↔ LOM path",
    "",
    "A cmdAbl path names an object by its names (`/2-808 Core Kit/808 Core Kit/Snare Drum`); every object also has a LOM",
    "path, built from its scope and position (`lomPath`). The scope selects the LOM list:",
    "",
    "| Scope | LOM list |",
    "| --- | --- |",
    ...SCOPE_LIST.map(([scope, list]) => `| \`${scope}\` | \`${list}\` |`),
    "",
    "| Kind | Scope | cmdAbl path | LOM path |",
    "| --- | --- | --- | --- |",
    ...input.pathExamples.map((e) => `| ${e.kind} | ${e.scope} | \`${e.cmdablPath}\` | \`${e.lomPath}\` |`),
    "",
    "## Port methods ↔ SDK call or script operation ↔ LOM",
    "",
    "What a module's port method does in Live. `sdk` calls need no Remote Script; `script` ones need it.",
    "",
    "| Port method | Via | SDK call / operation | LOM | Note |",
    "| --- | --- | --- | --- | --- |",
    ...input.ports.map(
      (p) => `| \`${p.port}\` | ${p.via} | ${cell(p.call)} | ${lomCell(p.lom)} | ${cell(p.note ?? "")} |`,
    ),
    "",
    "## Remote Script operations ↔ LOM",
    "",
    "What each operation reads (`get`), writes (`set`) or calls. A member the LOM reference does not document is",
    "marked; it exists in the Python API the script uses.",
    "",
    "| Operation | LOM members | SDK alternative |",
    "| --- | --- | --- |",
    ...input.ops.map((op) => {
      const uses = op.lom.map(use).join("<br>") || "–";
      const route = op.usesRoute ? "<br>+ walks the route (below)" : "";
      return `| \`${op.name}\` | ${uses}${route} | ${cell(op.sdkAlternative)} |`;
    }),
    "",
    "### Walking the route",
    "",
    "Every operation that takes `{scope, route}` finds its object through these members:",
    "",
    "| LOM member |",
    "| --- |",
    ...input.routeLom.map((u) => `| ${use(u)} |`),
    "",
    "## Runs through the script today",
    "",
    "The checklist for an SDK update: each item below is done by the Remote Script because the SDK did not offer",
    "it when this page was generated. When the SDK grows the call, switch the adapter, re-run",
    "`npm run docs:reference` and move the item to the `sdk` rows above.",
    "",
  ];
  for (const op of input.ops.filter((o) => o.name !== "hello")) {
    lines.push(`- \`${op.name}\` — ${prose(op.sdkAlternative)}`);
  }
  lines.push("");
  return lines.join("\n");
}
